import { QRCodeSVG } from "qrcode.react";
import { cn } from "../../utils/cn";

/**
 * Renders the QR code for a single ticket.
 *
 * IMPORTANT: The QR payload must be an OPAQUE token generated by the
 * backend. We never encode user IDs, ticket IDs, or anything else
 * predictable. The frontend only renders whatever the backend issued.
 */
export function TicketQRCode({
  token,
  size = 220,
  bgColor = "#ffffff",
  fgColor = "#0b0b10",
  className,
}) {
  if (!token) return null;
  return (
    <div
      className={cn(
        "rounded-2xl p-4 bg-white shadow-inner flex items-center justify-center",
        className
      )}
      role="img"
      aria-label="Ticket QR code — present this at entry"
    >
      <QRCodeSVG
        value={token}
        size={size}
        bgColor={bgColor}
        fgColor={fgColor}
        level="M"
        marginSize={2}
      />
    </div>
  );
}

export default TicketQRCode;